readonly REGION="asia-east1"
readonly SERVICE="rent-poc-demo"
readonly WORKFLOW="ci-deploy.yml"
readonly WIF_POOL="github"
readonly WIF_PROVIDER_ID="rent-poc"
readonly DB_INSTANCE_NAME="rent-poc-demo-pg"
readonly DB_NAME="rentpoc"
readonly SCHEDULER_SA_NAME="rent-poc-scheduler"
readonly PROXY_PORT="54320"
readonly MAX_INSTANCES=3
readonly POOL_MAX=5
readonly MONTHLY_ESTIMATE="9.81"
# 勾選順序即 MIL-92 票面與 MIL-91 留言的「切換前檢查清單」
readonly SEED_ROLES=(OWNER MANAGER MASTER_LESSOR TENANT OPERATOR)
readonly SEED_ROLE_LABELS=("屋主" "代管業者" "包租業者" "承租人" "平台營運者")

PROXY_PID=""

stop_proxy() {
  if [[ -n "$PROXY_PID" ]]; then
    kill "$PROXY_PID" >/dev/null 2>&1 || true
    wait "$PROXY_PID" 2>/dev/null || true
    PROXY_PID=""
  fi
}

# 中斷或結束時一定關掉 Auth Proxy，不留背景行程
trap stop_proxy EXIT

# create_if_missing "描述" "檢查指令" "建立指令"：重跑時略過已存在的資源
create_if_missing() {
  local description="$1" check="$2" create="$3"
  if eval "$check" >/dev/null 2>&1; then
    printf '  %s✓ 已存在%s %s\n' "$GREEN" "$RESET" "$description"
  else
    eval "$create" >/dev/null
    printf '  %s✓ 已建立%s %s\n' "$GREEN" "$RESET" "$description"
  fi
}

# grant_quiet：加 IAM 綁定，不把整份 policy 印到畫面
grant_quiet() {
  "$@" --quiet >/dev/null
}

# store_secret_for NAME VALUE SA_EMAIL...：新增 Secret Manager 的版本，只讓指定的 service account 能讀
store_secret_for() {
  local name="$1" value="$2" sa
  shift 2
  if ! gcloud secrets describe "$name" >/dev/null 2>&1; then
    gcloud secrets create "$name" --replication-policy=user-managed --locations="$REGION" --quiet >/dev/null
  fi
  printf '%s' "$value" | gcloud secrets versions add "$name" --data-file=- --quiet >/dev/null
  for sa in "$@"; do
    grant_quiet gcloud secrets add-iam-policy-binding "$name" \
      --member="serviceAccount:${sa}" --role=roles/secretmanager.secretAccessor
  done
  printf '  %s✓ 已存入%s Secret Manager：%s\n' "$GREEN" "$RESET" "$name"
}

secret_exists() {
  gcloud secrets versions access latest --secret="$1" >/dev/null 2>&1
}

secret_value() {
  gcloud secrets versions access latest --secret="$1"
}

# 資料庫密碼用十六進位字串，放進連線字串不需要跳脫
new_password() {
  openssl rand -hex 24
}

# url_password URL：取出 postgres://user:密碼@... 的密碼
url_password() {
  printf '%s' "$1" | sed -E 's#^postgres://[^:]*:([^@]*)@.*#\1#'
}

# proxy_url USER PASSWORD：經本機 Auth Proxy 連資料庫的連線字串
proxy_url() {
  printf 'postgres://%s:%s@127.0.0.1:%s/%s' "$1" "$2" "$PROXY_PORT" "$DB_NAME"
}

start_proxy() {
  stop_proxy
  command -v cloud-sql-proxy >/dev/null 2>&1 || { warn "找不到 cloud-sql-proxy。執行 brew install cloud-sql-proxy 後重跑。"; exit 1; }
  cloud-sql-proxy --gcloud-auth --address 127.0.0.1 --port "$PROXY_PORT" "$DB_CONNECTION_NAME" >"${TMPDIR:-/tmp}/rent-poc-proxy.log" 2>&1 &
  PROXY_PID=$!
  local attempt
  for attempt in $(seq 1 30); do
    if (echo > "/dev/tcp/127.0.0.1/${PROXY_PORT}") 2>/dev/null; then
      printf '  %s✓ Auth Proxy 已啟動%s（127.0.0.1:%s）\n' "$GREEN" "$RESET" "$PROXY_PORT"
      return 0
    fi
    sleep 1
  done
  cat "${TMPDIR:-/tmp}/rent-poc-proxy.log" >&2
  warn "Auth Proxy 30 秒內沒有就緒。"
  exit 1
}

# run_sql URL SQL：用 repo 的 pg 套件執行一句 SQL，每列印一行 JSON。不依賴 psql。
run_sql() {
  DATABASE_URL="$1" SQL_TEXT="$2" node -e '
    const pg = require("pg");
    const client = new pg.Client({ connectionString: process.env.DATABASE_URL });
    client.connect()
      .then(() => client.query(process.env.SQL_TEXT))
      .then((r) => { for (const row of r.rows ?? []) console.log(JSON.stringify(row)); })
      .catch((e) => { console.error(e.message); process.exitCode = 1; })
      .finally(() => client.end());
  '
}

# require_typed "要輸入的字" "說明"：花錢或不可復原的動作前，要求操作者逐字輸入確認
require_typed() {
  local phrase="$1" reply=""
  until [[ "$reply" == "$phrase" ]]; do
    printf '  %s? %s%s ' "$YELLOW" "$2" "$RESET"
    read -r reply || exit 1
    [[ "$reply" == "$phrase" ]] || warn "輸入不符，沒有執行。要停止請按 Ctrl-C。"
  done
}

checklist_item() {
  say "$1"
  note "$2"
  confirm "這一項已確認，或你接受 demo 先不處理？" || { warn "先處理這一項，再重跑這個腳本。"; exit 1; }
}

latest_run_on_demo() {
  gh run list --workflow "$WORKFLOW" --branch demo --limit 1 --json databaseId --jq '.[0].databaseId // ""'
}

run_wizard() {

# 從 repo 根目錄執行，gh 與 node 才找得到 repo 與套件。設定值存在 .env.deploy（已被 .gitignore 排除），重跑時沿用。
cd "$(dirname "$0")/.."
ENV_FILE=".env.deploy"

TOTAL_STAGES=16

banner "rent-poc：demo 從 SQLite 加 Litestream 切到 Cloud SQL"

stage "切換前須知與工具"
warn "切換期間寫入 demo 的資料會遺失，舊資料不搬。切換時不做 demo，也不得放真實個資。"
say "這個腳本假設第一次部署的 GCP 專案、Artifact Registry、service account 與 Workload Identity 都已建立。"
