if ! command -v gcloud >/dev/null 2>&1; then
  warn "沒有找到 gcloud。請先安裝：https://cloud.google.com/sdk/docs/install"
  exit 1
fi
gcloud auth list --filter=status:ACTIVE --format='value(account)' | grep -q . || gcloud auth login
note "目前的 Google 帳號：$(gcloud auth list --filter=status:ACTIVE --format='value(account)')"
gh auth status >/dev/null 2>&1 || gh auth login
GITHUB_REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
note "目前的 repo：${GITHUB_REPO}"
if ! command -v cloud-sql-proxy >/dev/null 2>&1; then
  if confirm "沒有找到 cloud-sql-proxy。要用 Homebrew 安裝嗎？"; then
    brew install cloud-sql-proxy
  else
    warn "請先安裝 cloud-sql-proxy：https://cloud.google.com/sql/docs/postgres/sql-proxy"
    exit 1
  fi
fi
[[ -d node_modules/pg ]] || { say "安裝套件（migration 與種子需要）。"; npm ci --ignore-scripts; }
ask GCP_PROJECT_ID "GCP 專案 ID（第一次部署時建立的那個）："
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
gcloud config set project "$GCP_PROJECT_ID" --quiet >/dev/null 2>&1
GCP_PROJECT_NUMBER=$(gcloud projects describe "$GCP_PROJECT_ID" --format='value(projectNumber)')
write_env GCP_PROJECT_NUMBER "$GCP_PROJECT_NUMBER"
DEPLOY_SA="rent-poc-deployer@${GCP_PROJECT_ID}.iam.gserviceaccount.com"
RUNTIME_SA="rent-poc-runtime@${GCP_PROJECT_ID}.iam.gserviceaccount.com"
