APP_ORIGIN="https://${SERVICE}-${GCP_PROJECT_NUMBER}.${REGION}.run.app"
DB_CONNECTION_NAME="${GCP_PROJECT_ID}:${REGION}:${DB_INSTANCE_NAME}"
gcloud iam service-accounts describe "$RUNTIME_SA" >/dev/null 2>&1 || { warn "找不到 $RUNTIME_SA。先完成第一次部署的設定。"; exit 1; }
