checklist_item "6. 簽章人員只從自家指派居間（MIL-200）" \
  "開放給真實使用者或 pilot 前必須完成。"
pause "六項都確認後，按 Enter。"

stage "啟用 API、設定權限與 Workload Identity"
gcloud services enable sqladmin.googleapis.com cloudscheduler.googleapis.com secretmanager.googleapis.com \
  storage.googleapis.com run.googleapis.com --quiet
printf '  %s✓ API 已啟用%s\n' "$GREEN" "$RESET"
create_if_missing "Cloud Scheduler 用的 service account $SCHEDULER_SA_NAME" \
  "gcloud iam service-accounts describe '$SCHEDULER_SA'" \
  "gcloud iam service-accounts create '$SCHEDULER_SA_NAME' --display-name='rent-poc Cloud Scheduler' --quiet"
