  --member="serviceAccount:${RUNTIME_SA}" --role=roles/cloudsql.client
grant_quiet gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" \
  --member="serviceAccount:${DEPLOY_SA}" --role=roles/cloudsql.client
printf '  %s✓ 執行用與部署用 service account 都有 Cloud SQL Client%s\n' "$GREEN" "$RESET"
say "部署只在 demo 分支。把 Workload Identity 的條件從 main 改成 demo。"
GITHUB_REPO_ID=$(gh api "repos/${GITHUB_REPO}" --jq .id)
