  --quiet >/dev/null
printf '  %s✓ Workload Identity 只接受 refs/heads/demo%s\n' "$GREEN" "$RESET"
pause "按 Enter 繼續。"

stage "建立 Cloud SQL 執行個體（開始計費）"
warn "下一步會建立 Cloud SQL 執行個體，從建立當下開始計費。"
say "規格：PostgreSQL 18、Enterprise 版、db-f1-micro、SSD 10 GiB、單區、公開 IP、${REGION}。"
note "每日自動備份（台灣時間 02:00）。公開 IP 沒有授權網路，只有 Auth Proxy 與 Cloud Run 連得進去。"
say "預估每月約 US\$${MONTHLY_ESTIMATE}。GCP 試用額度 US\$300 足以涵蓋。"
note "不指定 Enterprise 版時，預設是 Enterprise Plus，費用高很多。腳本已明確指定。"
note "db-f1-micro 是 shared core，沒有 SLA，demo 接受。pilot 前升規格。"
if gcloud sql instances describe "$DB_INSTANCE_NAME" >/dev/null 2>&1; then
  printf '  %s✓ 已存在%s 執行個體 %s，略過建立。\n' "$GREEN" "$RESET" "$DB_INSTANCE_NAME"
else
  require_typed "建立 Cloud SQL" "要建立並開始計費，請輸入「建立 Cloud SQL」；不建立請按 Ctrl-C："
  say "建立中，約需 5 到 10 分鐘。"
  gcloud sql instances create "$DB_INSTANCE_NAME" \
    --database-version=POSTGRES_18 --edition=ENTERPRISE --tier=db-f1-micro \
    --region="$REGION" --storage-type=SSD --storage-size=10GB \
    --availability-type=ZONAL --assign-ip \
    --backup --backup-start-time=18:00 --quiet
fi
create_if_missing "資料庫 $DB_NAME" \
  "gcloud sql databases describe '$DB_NAME' --instance='$DB_INSTANCE_NAME'" \
  "gcloud sql databases create '$DB_NAME' --instance='$DB_INSTANCE_NAME' --quiet"
write_env CLOUDSQL_INSTANCE "$DB_CONNECTION_NAME"
pause "按 Enter 繼續。"

stage "確認 PostgreSQL 主版本"
DB_VERSION=$(gcloud sql instances describe "$DB_INSTANCE_NAME" --format='value(databaseVersion)')
note "執行個體：${DB_VERSION}"
CI_MAJOR=$(grep -E '^\s+image: postgres:[0-9]+' .github/workflows/ci-deploy.yml | head -1 | sed -E 's/.*postgres:([0-9]+).*/\1/')
note "CI 與 PGlite 對齊的主版本：${CI_MAJOR}"
if [[ "$DB_VERSION" != "POSTGRES_${CI_MAJOR}" ]]; then
  warn "執行個體是 ${DB_VERSION}，CI 是 postgres:${CI_MAJOR}。主版本不同時，測試結果不能代表 demo。"
  confirm "仍要繼續嗎？" || exit 1
fi
printf '  %s✓ 主版本檢查完成%s\n' "$GREEN" "$RESET"
pause "按 Enter 繼續。"

stage "產生資料庫密碼並存進 Secret Manager"
say "三組密碼：postgres 管理者、app_owner（migration）、app_rw（應用程式）。畫面不顯示。"
if secret_exists cloudsql-postgres-password; then
  note "postgres 管理者密碼已存在，沿用。"
  POSTGRES_PASSWORD=$(secret_value cloudsql-postgres-password)
else
  POSTGRES_PASSWORD=$(new_password)
  store_secret_for cloudsql-postgres-password "$POSTGRES_PASSWORD"
fi
gcloud sql users set-password postgres --instance="$DB_INSTANCE_NAME" --password="$POSTGRES_PASSWORD" --quiet >/dev/null
if secret_exists migrate-database-url; then
  OWNER_PASSWORD=$(url_password "$(secret_value migrate-database-url)")
  note "app_owner 的連線字串已存在，沿用。"
else
  OWNER_PASSWORD=$(new_password)
  # migration 在 GitHub Actions 經 Auth Proxy（127.0.0.1:5432）執行。只有部署用身分讀得到，執行用身分讀不到。
  store_secret_for migrate-database-url "postgres://app_owner:${OWNER_PASSWORD}@127.0.0.1:5432/${DB_NAME}" "$DEPLOY_SA"
fi
if secret_exists database-url; then
  RW_PASSWORD=$(url_password "$(secret_value database-url)")
  note "app_rw 的連線字串已存在，沿用。"
else
  RW_PASSWORD=$(new_password)
  # Cloud Run 經 Unix socket 連線。只有執行用身分讀得到。
  store_secret_for database-url "postgres://app_rw:${RW_PASSWORD}@/${DB_NAME}?host=/cloudsql/${DB_CONNECTION_NAME}" "$RUNTIME_SA"
fi
if secret_exists auth-secret; then
  note "AUTH_SECRET 已存在，沿用。"
else
  store_secret_for auth-secret "$(openssl rand -base64 32)" "$RUNTIME_SA"
fi
note "換 auth-secret 會讓尚未使用的登入驗證碼全部失效，已建立的 session 不受影響。"
pause "按 Enter 繼續。"

stage "建立角色並執行 migration"
say "第一個 migration（0001）建立 app_owner 與 app_rw，必須由 postgres 執行。不用 Console 建角色。"
start_proxy
POSTGRES_URL=$(proxy_url postgres "$POSTGRES_PASSWORD")
if DATABASE_URL="$POSTGRES_URL" npm run --silent db:migrate; then
  printf '  %s✓ 管理者身分已執行 migration%s\n' "$GREEN" "$RESET"
else
  warn "管理者身分在 0001 之後失敗。Cloud SQL 的 postgres 不是 superuser，可能不能切換成 app_owner。"
  say "改成先設 app_owner 的密碼，再由 app_owner 執行其餘的 migration。已執行的檔案不會重做。"
  run_sql "$POSTGRES_URL" "ALTER ROLE app_owner PASSWORD '${OWNER_PASSWORD}'" >/dev/null
  DATABASE_URL="$(proxy_url app_owner "$OWNER_PASSWORD")" npm run --silent db:migrate
fi
run_sql "$POSTGRES_URL" "ALTER ROLE app_owner PASSWORD '${OWNER_PASSWORD}'" >/dev/null
run_sql "$POSTGRES_URL" "ALTER ROLE app_rw PASSWORD '${RW_PASSWORD}'" >/dev/null
printf '  %s✓ app_owner 與 app_rw 的密碼已設定%s\n' "$GREEN" "$RESET"
say "用 app_owner 重跑一次，確認 CI 的路徑可用，而且沒有待執行的項目。"
RERUN_OUTPUT=$(DATABASE_URL="$(proxy_url app_owner "$OWNER_PASSWORD")" npm run --silent db:migrate)
[[ "$RERUN_OUTPUT" == *"沒有待執行的 migration"* ]] || { warn "app_owner 重跑時還有待執行的 migration。"; exit 1; }
printf '  %s✓ app_owner 重跑 migration，沒有待執行的項目%s\n' "$GREEN" "$RESET"
pause "按 Enter 繼續。"

stage "建立檔案用的 Cloud Storage bucket"
for kind in signed general; do
  bucket="${GCP_PROJECT_ID}-files-${kind}"
  create_if_missing "bucket gs://${bucket}" \
    "gcloud storage buckets describe 'gs://${bucket}'" \
    "gcloud storage buckets create 'gs://${bucket}' --location='${REGION}' --uniform-bucket-level-access --public-access-prevention --quiet"
  gcloud storage buckets add-iam-policy-binding "gs://${bucket}" \
    --member="serviceAccount:${RUNTIME_SA}" --role=roles/storage.objectUser --quiet >/dev/null
done
gcloud storage buckets update "gs://${GCP_PROJECT_ID}-files-signed" --versioning --quiet >/dev/null
printf '  %s✓ 已簽文件的 bucket 開啟版本控制，只授權執行身分%s\n' "$GREEN" "$RESET"
note "workflow 會把 FILE_STORE=gcs 與兩個 bucket 名稱寫進 Cloud Run 的環境變數。"
pause "按 Enter 繼續。"

stage "輸入五個示範帳號的 email"
say "示範資料的帳號各一：屋主、代管業者、包租業者、承租人、平台營運者。"
say "登入用 email 驗證碼。目前的寄信方式是 log，驗證碼顯示在 /demo/otp，不會真的寄信。"
warn "只填你自己控制的位址。不得填真實第三人的 email。五個位址必須各不相同。"
for i in "${!SEED_ROLES[@]}"; do
  email_var="DEMO_SEED_${SEED_ROLES[$i]}_EMAIL"
  ask "$email_var" "${SEED_ROLE_LABELS[$i]}的 email："
  write_env "$email_var" "${!email_var}"
done
pause "按 Enter 繼續。"

stage "執行示範資料種子"
say "種子用 app_rw 連線，與應用程式相同，經既有的帳號、組織、物件函式建立，RLS 與稽核照常生效。"
say "能重複執行：已存在的資料不會再建一次。"
DATABASE_URL="$(proxy_url app_rw "$RW_PASSWORD")" \
  DEMO_SEED_OWNER_EMAIL="$DEMO_SEED_OWNER_EMAIL" DEMO_SEED_MANAGER_EMAIL="$DEMO_SEED_MANAGER_EMAIL" \
  DEMO_SEED_MASTER_LESSOR_EMAIL="$DEMO_SEED_MASTER_LESSOR_EMAIL" DEMO_SEED_TENANT_EMAIL="$DEMO_SEED_TENANT_EMAIL" \
  DEMO_SEED_OPERATOR_EMAIL="$DEMO_SEED_OPERATOR_EMAIL" \
  npm run --silent db:seed
printf '  %s✓ 種子以 0 結束%s\n' "$GREEN" "$RESET"
pause "按 Enter 繼續。"

stage "驗證資料庫角色、連線池隔離與連線數"
RW_URL="$(proxy_url app_rw "$RW_PASSWORD")"
say "app_owner 與 app_rw 都不得有 BYPASSRLS。結果兩列的 rolbypassrls 都必須是 false。"
run_sql "$RW_URL" "SELECT rolname, rolsuper, rolbypassrls FROM pg_roles WHERE rolname IN ('app_owner','app_rw') ORDER BY rolname"
confirm "兩列的 rolsuper 與 rolbypassrls 都是 false？" || { warn "停下來查原因。"; exit 1; }
say "連線池隔離：連線池只開 1 條連線，連續兩個請求用不同組織，後者讀不到前者的物件。"
DATABASE_URL="$RW_URL" node -e '
  const pg = require("pg");
  const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL, max: 1 });
  async function countFor(orgId) {
    const client = await pool.connect();
    try {
      await client.query("BEGIN");
      await client.query("SELECT set_config($1, $2, true)", ["app.org_id", orgId]);
      const r = await client.query("SELECT count(*)::int AS n FROM org.properties");
      await client.query("COMMIT");
      return r.rows[0].n;
    } finally { client.release(); }
  }
  (async () => {
    const orgs = await pool.query("SELECT id, name FROM control.orgs WHERE kind = $1 OR name LIKE $2 ORDER BY name", ["owner", "示範%"]);
    const owner = orgs.rows.find((o) => o.name === "示範屋主");
    const other = orgs.rows.find((o) => o.name === "示範代管股份有限公司");
    if (!owner || !other) throw new Error("找不到示範屋主或示範代管業者的組織");
    const first = await countFor(owner.id);
    const second = await countFor(other.id);
    const third = await countFor(owner.id);
    console.log(JSON.stringify({ 屋主讀到的物件數: first, 代管業者讀到的物件數: second, 再換回屋主: third }));
    if (first < 1 || second !== 0 || third !== first) throw new Error("連線池隔離不符預期");
  })().catch((e) => { console.error(e.message); process.exitCode = 1; }).finally(() => pool.end());
'
printf '  %s✓ 連線池隔離通過%s\n' "$GREEN" "$RESET"
MAX_CONNECTIONS=$(run_sql "$RW_URL" "SHOW max_connections" | sed -E 's/.*:"([0-9]+)".*/\1/')
PRODUCT=$((MAX_INSTANCES * POOL_MAX))
say "max_connections = ${MAX_CONNECTIONS}。Cloud Run max-instances ${MAX_INSTANCES} 乘以 pg.Pool 上限 ${POOL_MAX} = ${PRODUCT}。"
if (( PRODUCT >= MAX_CONNECTIONS )); then
  warn "乘積不低於 max_connections。先降低 workflow 的 max-instances 或 PG_POOL_MAX。"
  exit 1
fi
note "scheduler 與 job 也用同一個連線池，保留餘裕給管理連線。這兩個數字要記在 MIL-92。"
write_env MAX_CONNECTIONS "$MAX_CONNECTIONS"
stop_proxy
pause "按 Enter 繼續。"

stage "寫入 GitHub repo variables"
say "這些都不是機密。機密都在 Secret Manager。"
set_var CLOUDSQL_INSTANCE "$DB_CONNECTION_NAME"
set_var PLATFORM_OPERATOR_EMAILS "$DEMO_SEED_OPERATOR_EMAIL"
set_var GCP_PROJECT_ID "$GCP_PROJECT_ID"
set_var GCP_PROJECT_NUMBER "$GCP_PROJECT_NUMBER"
set_var DEPLOY_SA "$DEPLOY_SA"
set_var RUNTIME_SA "$RUNTIME_SA"
note "WIF_PROVIDER 與 DOTTEDSIGN_ENABLED 沿用第一次部署的值。"
note "PLATFORM_OPERATOR_EMAILS 只放一個 email：workflow 的 env_vars 以逗號分隔。"
note "LITESTREAM_BUCKET 已不再使用，保留到舊資料到期（見最後一階段）。"
pause "按 Enter 繼續。"

stage "請主控推 demo（觸發部署）"
warn "這個腳本不建立 dev 與 demo 分支，也不推 demo。"
step "回到主控對話，請主控把 dev 快轉推到 demo。這一步會觸發部署。"
step "部署包含：建置映像、用 app_owner 跑 migration、部署到 Cloud Run（掛 Cloud SQL 與 secrets）。"
pause "主控回報已推 demo 之後，按 Enter。"
RUN_ID=""
until [[ -n "$RUN_ID" ]]; do
  RUN_ID=$(latest_run_on_demo)
  [[ -n "$RUN_ID" ]] || { warn "demo 分支還沒有 ${WORKFLOW} 的執行。"; pause "確認主控已推 demo 後，按 Enter 重新檢查。"; }
done
say "等待這次部署結束（run ${RUN_ID}）。"
gh run watch "$RUN_ID" --exit-status
curl --fail --silent --show-error --retry 5 --retry-delay 5 "${APP_ORIGIN}/api/health" >/dev/null
printf '  %s✓ /api/health 回 200%s %s\n' "$GREEN" "$RESET" "$APP_ORIGIN"
pause "按 Enter 繼續。"

stage "建立 Cloud Scheduler 的 5 個 job"
say "demo 的週期依 ADR-0020：drain 每小時，scan-timers 每日 00:10，anchor-audit 00:30，verify-audit 01:00（台灣時間）。"
note "服務的 OIDC 驗證設定（JOBS_OIDC_*）已由 workflow 寫進環境變數，不用手動更新。"
create_job() { # 名稱 排程 逾時 重試次數
  local job="rent-poc-$1" schedule="$2" deadline="$3" retries="$4"
  local verb=create
  gcloud scheduler jobs describe "$job" --location "$REGION" >/dev/null 2>&1 && verb=update
  local args=(--location "$REGION" --schedule "$schedule" --time-zone "Asia/Taipei"
    --uri "${APP_ORIGIN}/api/internal/jobs/$1" --http-method POST
    --oidc-service-account-email "$SCHEDULER_SA" --oidc-token-audience "$APP_ORIGIN"
    --attempt-deadline "$deadline" --max-retry-attempts "$retries")
  [[ "$retries" != "0" ]] && args+=(--min-backoff 30s)
  gcloud scheduler jobs "$verb" http "$job" "${args[@]}" --quiet >/dev/null
  printf '  %s✓ 已設定%s %s（%s）\n' "$GREEN" "$RESET" "$job" "$schedule"
}
create_job drain-inbox "0 * * * *" 300s 3
create_job drain-outbox "0 * * * *" 300s 3
create_job scan-timers "10 0 * * *" 300s 3
create_job anchor-audit "30 0 * * *" 120s 0
create_job verify-audit "0 1 * * *" 300s 0
pause "按 Enter 繼續。"

stage "冒煙測試與驗收"
DEMO_PASSWORD_HINT="Basic Auth 帳號 demo，密碼在 Secret Manager 的 demo-basic-auth-password"
say "自動檢查："
[[ "$(curl -s -o /dev/null -w '%{http_code}' -X POST "${APP_ORIGIN}/api/internal/jobs/drain-inbox")" == "401" ]] \
  && printf '  %s✓ 沒有 token 的 job 呼叫回 401%s\n' "$GREEN" "$RESET" \
  || { warn "沒有 token 的 job 呼叫沒有回 401。立刻停用排程並檢查環境變數。"; exit 1; }
for job in drain-inbox drain-outbox scan-timers anchor-audit verify-audit; do
  gcloud scheduler jobs run "rent-poc-$job" --location "$REGION" >/dev/null
  printf '  %s✓ 已手動觸發%s rent-poc-%s\n' "$GREEN" "$RESET" "$job"
done
say "等 30 秒後，看每個 job 最近一次的結果。每一列的 status 必須是 OK 或 HTTP 狀態是 2xx。"
sleep 30
for job in drain-inbox drain-outbox scan-timers anchor-audit verify-audit; do
  note "rent-poc-$job"
  gcloud logging read "resource.type=\"cloud_scheduler_job\" AND resource.labels.job_id=\"rent-poc-$job\"" \
    --limit 2 --format='value(timestamp,jsonPayload.status,httpRequest.status)' || true
done
confirm "五個 job 都回 2xx？" || { warn "查 Cloud Run 的 log：gcloud run services logs read ${SERVICE} --region ${REGION} --limit 50"; exit 1; }
say "第一次 anchor-audit 要保存 FreeTSA 的回執。看 log 的 status 是 anchored 或 no_changes："
gcloud logging read 'jsonPayload.component="audit-anchor"' --limit 5 --format='value(timestamp,severity,jsonPayload.message)' || true
confirm "第一次 anchor-audit 已保存回執，或沒有新事件可錨定？" || { warn "查 FreeTSA 是否中斷。"; exit 1; }
open_url "$APP_ORIGIN"
note "$DEMO_PASSWORD_HINT"
step "用五個示範帳號各登入一次：輸入 email，驗證碼從 ${APP_ORIGIN}/demo/otp 取。"
step "屋主登入後：確認看得到示範物件，建立一個新物件與一份合約。"
step "送簽，再用 mock 模式推進到簽署完成，最後下載文件。"
step "承租人帳號要等合約送簽後才有承租人身分，這是預期行為。"
step "平台營運者登入後，確認看得到審核台。"
confirm "五個帳號都登入成功，主流程走完？" || { warn "停下來查原因。回滾步驟在最後一階段。"; exit 1; }
pause "按 Enter 繼續。"

stage "記錄與回滾說明"
EXPIRY=$(date -v+14d +%F 2>/dev/null || date -d '+14 days' +%F)
OLD_BUCKET=$(_existing LITESTREAM_BUCKET || true)
OLD_BUCKET="${OLD_BUCKET:-${GCP_PROJECT_ID}-demo-db}"
say "把下面的值記在 MIL-92："
step "max_connections = ${MAX_CONNECTIONS}，max-instances ${MAX_INSTANCES} 乘以 PG_POOL_MAX ${POOL_MAX} = ${PRODUCT}。"
step "舊的 Litestream 資料（gs://${OLD_BUCKET}）保留 2 週，到期日 ${EXPIRY}。到期前不要刪。"
step "到期後可刪除舊 bucket，並用 gh variable delete LITESTREAM_BUCKET 移除不再使用的變數。"
warn "回滾：冒煙失敗時，把 Cloud Run 流量切回切換前的 revision（docs/deployment.md 的「回滾」）。"
note "舊 revision 仍從 Litestream 還原資料。切換後寫入 Cloud SQL 的資料不會回到 SQLite。"
note "還要在 dev 分支 revert 這次合併，避免下一次部署又換版。這一步請主控處理。"

finish
say "demo 網址：$APP_ORIGIN"
say "日常操作（demo 當天保持開機、回滾、換密碼、清空資料）見 docs/deployment.md。"
printf '\n'
}

run_wizard "$@"; exit
